import json
from collections import deque

def fill_enclosed_regions(grid):
    """Use flood fill from edges to find exterior, then fill remaining zeros as interior"""
    rows = len(grid)
    cols = len(grid[0])

    # Create a copy with all zeros replaced by non-zero (treating 0 as water/interior candidate)
    # Mark all cells reachable from outside as "exterior"
    visited = [[False] * cols for _ in range(rows)]
    queue = deque()

    # Start from all boundary zeros
    for r in range(rows):
        if grid[r][0] == 0:
            queue.append((r, 0))
            visited[r][0] = True
        if grid[r][cols-1] == 0:
            queue.append((r, cols-1))
            visited[r][cols-1] = True
    for c in range(cols):
        if grid[0][c] == 0:
            queue.append((0, c))
            visited[0][c] = True
        if grid[rows-1][c] == 0:
            queue.append((rows-1, c))
            visited[rows-1][c] = True

    while queue:
        r, c = queue.popleft()
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and not visited[nr][nc] and grid[nr][nc] == 0:
                visited[nr][nc] = True
                queue.append((nr, nc))

    # Now fill any zeros that weren't visited (enclosed regions)
    result = [row[:] for row in grid]
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 0 and not visited[r][c]:
                # Find the color surrounding this region
                neighbors = []
                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < rows and 0 <= nc < cols:
                        neighbors.append(grid[nr][nc])

                # Use the most common neighbor color
                from collections import Counter
                most_common = Counter(neighbors).most_common(1)[0][0]
                result[r][c] = most_common

    return result

